  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape' && modal.classList.contains('open')) {
      closeModal();
    }
  });

  // Close modal when clicking outside the modal content
  modal.addEventListener('click', (event) => {
    if (event.target === modal) {
      closeModal();
    }
  });

  // Function to open the modal
  function openModal() {
    modal.classList.add('open');
    modal.setAttribute('aria-hidden', 'false');

    // Move focus to the cancel button for better keyboard navigation
    cancelBtn.focus();

    // Prevent body scroll when modal is open
    document.body.style.overflow = 'hidden';
  }

  // Function to close the modal
  function closeModal() {
    modal.classList.remove('open');
    modal.setAttribute('aria-hidden', 'true');

    // Restore body scroll
    document.body.style.overflow = '';

    // Return focus to the trigger button
    triggerBtn.focus();
  }

  // Function to handle delete confirmation
  function handleDelete() {
    // Simulate deletion
    console.log('Image deleted from library');

    // Close the modal
    closeModal();

    // Optional: Show success message or remove the image card
    const imageCard = triggerBtn.closest('.image-card');
    if (imageCard) {
      imageCard.style.opacity = '0.5';
      imageCard.setAttribute('aria-hidden', 'true');
      setTimeout(() => {
        imageCard.remove();
      }, 300);
    }
  }
});
