  .modal-overlay {
    background-color: Canvas;
  }

  .modal-content {
    border: 2px solid CanvasText;
    background-color: Canvas;
    color: CanvasText;
  }

  .modal-content h2,
  .modal-content p {
    color: CanvasText;
  }

  .btn-primary,
  .btn-secondary {
    border: 2px solid ButtonText;
  }
}
